sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {

    if (event.payload.item.id == "show_more") {
        api.setState("loadingItems", [{
            "path": event.payload.item.parentPath
        }]);
        api.setState("currentPath", event.payload.item.parentPath);

        api.data.fetch_more_children_for_given_entity_1.execute({
            "entityId": event.payload.item.parentId,
            "childrenIds": event.payload.item.parentChildrenIds,
            "remainingChildren": event.payload.item.parentRemainingChildren,
            "path": event.payload.item.parentPath
        });

    } else {
        if (event.payload.sysId == api.context.props.sysId)
            return;

        const payload = {
            route: 'record',
            fields: {
                table: 'sn_grc_profile',
                sysId: event.payload.item.id
            }
        };


        const {
            emit
        } = api;
        emit('NAV_ITEM_SELECTED', payload);
    }

}
